  ('019fc105-11ad-7f0b-821a-421b9b738b98', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'kind', 'kind', 'Protocol family: ''oauth2'' (manual endpoint configuration) or ''oidc'' (discovery + JWKS-verified id_token). Future kinds (''saml'') will use a different field set.', '{"has_guard":true}', true, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 2, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-11be-7c9c-854c-48633ee7d389', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'display_name', 'display_name', 'Human-readable label for client UIs (e.g. ''Sign in with Google'', ''Acme Okta''). Exposed via the public-safe view.', NULL, true, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 3, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-11ce-7bdc-8c9f-6099b2ece03d', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'enabled', 'enabled', 'Whether sign-in via this provider is currently allowed. Toggled by enable_identity_provider / disable_identity_provider admin procedures. Disabled providers remain in the public-safe view as enabled=false so client UIs can grey out the button.', '{"has_guard":true}', true, false, '{"value":true}', NULL, NULL, NULL, NULL, '{"name":"boolean"}', 4, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-11e4-70d1-918e-b2f990b9f533', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'authorization_url', 'authorization_url', 'OAuth2 authorization endpoint (where the user is redirected to grant consent). Required when kind = ''oauth2''; for kind = ''oidc'' resolved from cached discovery_doc.', '{"has_guard":true}', false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 5, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-11ef-7973-868c-0f8eff17a534', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'token_url', 'token_url', 'OAuth2 token endpoint (exchanges authorization code for access/id tokens). Required when kind = ''oauth2''; for kind = ''oidc'' resolved from cached discovery_doc.', '{"has_guard":true}', false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 6, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-11fa-7723-bc61-c63917901c98', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'userinfo_url', 'userinfo_url', 'OAuth2 userinfo endpoint (returns the user profile given an access token). Required when kind = ''oauth2''; for kind = ''oidc'' resolved from cached discovery_doc or used as a fallback when the id_token does not contain the desired claims.', '{"has_guard":true}', false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 7, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-1205-7252-a4b2-372342626570', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'issuer_url', 'issuer_url', 'OIDC issuer URL. Discovery fetches {issuer}/.well-known/openid-configuration unless discovery_url_override is set. Required when kind = ''oidc''. Used for id_token ''iss'' claim verification.', '{"has_guard":true}', false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 8, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-1210-73f1-b14b-59066fec49f9', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'discovery_url_override', 'discovery_url_override', 'Optional non-standard discovery document URL. When NULL, discovery uses {issuer_url}/.well-known/openid-configuration. Used for IdPs that publish discovery at a non-spec path.', '{"has_guard":true}', false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 9, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-121c-7074-b70c-29f0988e8ea1', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'discovery_doc', 'discovery_doc', 'Cached OIDC discovery document (authorization_endpoint, token_endpoint, userinfo_endpoint, jwks_uri, issuer, etc.). Refreshed by a background job; auth-server reads endpoints from here at request time when kind = ''oidc''.', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"jsonb"}', 10, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-1227-70d3-96ef-ea89c2444a05', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'jwks', 'jwks', 'Cached JWKS document used to verify id_token signatures. Refreshed by a background job. NULL until first successful discovery + JWKS fetch.', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"jsonb"}', 11, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-1232-70c8-a2f7-631ded1e6964', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'jwks_fetched_at', 'jwks_fetched_at', 'Timestamp of the most recent successful JWKS fetch. Used by the background refresher to age out cache entries and to drive cold-start fetches when NULL.', NULL, false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"timestamptz"}', 12, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-123d-70a3-ac96-3f63bfe49f92', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'client_id', 'client_id', 'OAuth2 / OIDC client_id registered with the IdP. NULL for built-in rows until an admin sets it. Providers with NULL client_id or NULL client_secret_id are treated as not-configured by the sign-in path regardless of the enabled flag.', '{"has_guard":true}', false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"text"}', 13, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-1247-7fd8-ae55-970231890382', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'client_secret_id', 'client_secret_id', 'Pointer to the row in user_secrets that holds the OAuth2 client_secret (encrypted at rest). NULL only briefly between create_identity_provider and the first rotate_provider_secret. Rotation writes a new user_secrets row and atomically updates this column; the raw secret is never returned to clients.', '{"has_guard":true}', false, false, NULL, NULL, NULL, NULL, NULL, '{"name":"uuid"}', 14, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-1252-7115-a9dd-8398f7359e89', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'scopes', 'scopes', 'OAuth2 scopes requested in the authorization URL. For kind = ''oidc'' the admin procedure ensures ''openid'' is always present (silently prepended if missing).', '{"has_guard":true}', true, false, '{"cast":{"name":"text","array_dimensions":1},"value":[]}', NULL, NULL, NULL, NULL, '{"name":"text","array_dimensions":1}', 15, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-1268-7500-897b-b2c9e6b8356e', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'extra_authorization_params', 'extra_authorization_params', 'Extra query parameters merged into the authorization URL (e.g. {"prompt":"select_account"}). Admin procedure rejects reserved OAuth/OIDC keys: client_id, redirect_uri, state, nonce, code_challenge, code_challenge_method, response_type, scope.', '{"has_guard":true}', true, false, '{"cast":{"name":"jsonb"},"value":{}}', NULL, NULL, NULL, NULL, '{"name":"jsonb"}', 16, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-127f-7266-8a0c-d1be9d35c5ff', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'acceptable_client_ids', 'acceptable_client_ids', 'Multi-platform audience allow-list. When non-empty, id_token ''aud'' is validated against client_id OR any value here. Used when one IdP project issues tokens with platform-specific audiences (web vs iOS vs Android).', '{"has_guard":true}', true, false, '{"cast":{"name":"text","array_dimensions":1},"value":[]}', NULL, NULL, NULL, NULL, '{"name":"text","array_dimensions":1}', 17, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-1296-7df0-8b38-68efb9cc0e2e', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'email_optional', 'email_optional', 'When true, sign-in succeeds even if the IdP does not return a verified email. The user is provisioned without an email and can add one later. When false, missing email is a hard error.', '{"has_guard":true}', true, false, '{"value":false}', NULL, NULL, NULL, NULL, '{"name":"boolean"}', 18, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-12b1-756b-9dd1-307bbc1fa2b9', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'allow_link_by_email', 'allow_link_by_email', 'When true, an OAuth/OIDC sign-in whose IdP-verified email matches an existing user account auto-links the new identity to that account. When false, an existing-email collision raises IDENTITY_EMAIL_ALREADY_REGISTERED. Only honored when the IdP marks the email as verified.', '{"has_guard":true}', true, false, '{"value":false}', NULL, NULL, NULL, NULL, '{"name":"boolean"}', 19, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-12c8-7669-bf2f-b899e81319b5', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'skip_nonce_check', 'skip_nonce_check', 'OIDC only. When true, the auth server does not require / verify the ''nonce'' claim in id_token. ONLY enable for IdPs that demonstrably do not support nonce; weakens replay resistance.', '{"has_guard":true}', true, false, '{"value":false}', NULL, NULL, NULL, NULL, '{"name":"boolean"}', 20, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-12df-78cb-87bd-8ef36649dcf1', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-1171-72ca-849a-5ad7ac0b2fd3', 'pkce_enabled', 'pkce_enabled', 'When true, the auth server generates a PKCE code_verifier per authorization request, sends code_challenge with method = S256, and includes code_verifier in the token exchange. PKCE is handled entirely server-side. Default is true; only disable for IdPs that reject PKCE parameters.', '{"has_guard":true}', true, false, '{"value":true}', NULL, NULL, NULL, NULL, '{"name":"boolean"}', 21, NULL, NULL, NULL, NULL, NULL, '{}', 'app'),
  ('019fc105-13d8-70c3-9e8d-b4ef208c1d93', '019fc104-f28d-7b9c-8d9d-8f338def573c', '019fc105-13bf-7b4a-919a-37a5c5871c02', 'id', 'id', 'Unique identifier for each audit event (uuidv7 provides temporal ordering)', NULL, true, false, '{"function":"uuidv7"}', NULL, NULL, NULL, NULL, '{"name":"uuid"}', 0, NULL, NULL, NULL, NULL, NULL, '{}', 'module'),
